import math

def f(m, n, alpha):
    """Calculates m*ceil(n*alpha) - n*floor(m*alpha)"""
    if m <= 0 or n <= 0:
        return None
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha)

# Test case structure (assuming a placeholder alpha)
alpha_test = 1.2345
print(f"f(2, 3, {alpha_test}) = {f(2, 3, alpha_test)}")
print(f"f(3, 2, {alpha_test}) = {f(3, 2, alpha_test)}")

import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    try:
        lhs = m * math.ceil(n * alpha) - n * math.floor(m * alpha)
        return lhs == k
    except OverflowError:
        return False

k = 2310
alpha = math.sqrt(2)
limit = 50

found_pretty = []
for m in range(1, limit + 1):
    for n in range(1, limit + 1):
        if is_pretty(m, n, alpha, k):
            found_pretty.append((m, n))

print(f"Found {len(found_pretty)} pretty pairs for m, n <= {limit} with alpha=sqrt(2) and k={k}.")
if found_pretty:
    print("Example pretty pair:", found_pretty[0])

